macro_rules! filled_logo {
    ($mono:ident, $color:ident, $name:literal, $fill:literal, $outline:literal, $inner:literal) => {
        pub static $mono: Icon = Icon {
            name: concat!("simple-icons-", $name, "-filled"),
            view: 24.0,
            body: concat!(
                r#"<path fill="currentColor" d=""#,
                $outline,
                r#"" />"#,
                r##"<path fill="#fff" d=""##,
                $outline,
                $inner,
                r#"" />"#,
            ),
        };

        pub static $color: Icon = Icon {
            name: concat!("simple-icons-", $name, "-filled-color"),
            view: 24.0,
            body: concat!(
                r#"<path fill=""#,
                $fill,
                r#"" d=""#,
                $outline,
                r#"" />"#,
                r##"<path fill="#fff" d=""##,
                $outline,
                $inner,
                r#"" />"#,
            ),
        };
    };
}

macro_rules! bold_logo {
    ($mono:ident, $color:ident, $name:literal, $fill:literal, $stroke:literal, $d:literal) => {
        pub static $mono: Icon = Icon {
            name: concat!("simple-icons-", $name, "-bold"),
            view: 24.0,
            body: concat!(
                r#"<g transform="translate(12 12) scale(0.94) translate(-12 -12)">"#,
                r#"<path fill="currentColor" stroke="currentColor" stroke-linejoin="round" stroke-width=""#,
                $stroke, r#"" d=""#, $d, r#"" /></g>"#,
            ),
        };

        pub static $color: Icon = Icon {
            name: concat!("simple-icons-", $name, "-bold-color"),
            view: 24.0,
            body: concat!(
                r#"<g transform="translate(12 12) scale(0.94) translate(-12 -12)">"#,
                r#"<path fill=""#, $fill, r#"" stroke=""#, $fill, r#"" stroke-linejoin="round" stroke-width=""#,
                $stroke, r#"" d=""#, $d, r#"" /></g>"#,
            ),
        };
    };
}

macro_rules! logo {
    ($mono:ident, $color:ident, $name:literal, $fill:literal, $d:literal) => {
        pub static $mono: Icon = Icon {
            name: concat!("simple-icons-", $name),
            view: 24.0,
            body: concat!(r#"<path fill="currentColor" d=""#, $d, r#"" />"#),
        };

        pub static $color: Icon = Icon {
            name: concat!("simple-icons-", $name, "-color"),
            view: 24.0,
            body: concat!(r#"<path fill=""#, $fill, r#"" d=""#, $d, r#"" />"#),
        };
    };
}

