pub fn db_kind(kind: crate::connection::DbKind) -> &'static Icon {
    use crate::connection::DbKind;
    match kind {
        DbKind::Postgres => &POSTGRESQL_COLOR,
        DbKind::MySql => &MYSQL_COLOR,
        DbKind::Sqlite => &SQLITE_COLOR,
    }
}

pub fn db_kind_mono(kind: crate::connection::DbKind) -> &'static Icon {
    use crate::connection::DbKind;
    match kind {
        DbKind::Postgres => &POSTGRESQL,
        DbKind::MySql => &MYSQL,
        DbKind::Sqlite => &SQLITE,
    }
}
